{
  "name": "txl_desc_process",
  "confidence": "medium",
  "docstring": "Processes the next TX descriptor popped from a per-queue list, marking it as handled, validating Block-Ack/aggregation information when present, preparing the packet, and copying header/control bytes into an inline descriptor field for selected frame types.",
  "subsystem": "mac",
  "var_renames": {
    "a1": "pbd",
    "v4": "queue_id",
    "v6": "desc_popped",
    "v7": "agg_desc_count_ptr",
    "v8": "tx_desc",
    "v9": "tx_info",
    "v13": "hdr_type"
  },
  "struct_hints": [
    {
      "offset": 48,
      "meaning": "pbd.hdr_type: frame type code; 52 or 28 trigger inline header/control copy"
    },
    {
      "offset": 84,
      "meaning": "pbd.tx_info: packed TX control/status word containing queue bits, BA sequence bits, and BA-valid flag"
    },
    {
      "offset": 8,
      "meaning": "tx_desc.flags: bit 0x20 set after descriptor pop, bit 0x40 set after packet preparation/header copy"
    },
    {
      "offset": 12,
      "meaning": "tx_desc.agg_seq_offset: byte compared with Block-Ack sequence derived from tx_info"
    },
    {
      "offset": 13,
      "meaning": "tx_desc.tid: byte compared with QoS/BA header field during header copy"
    },
    {
      "offset": 224,
      "meaning": "tx_desc.hdr_copy_ptr: set to tx_desc + 228 when a header/control snapshot is copied inline"
    },
    {
      "offset": 228,
      "meaning": "tx_desc.hdr_inline: 34-byte inline buffer receiving copied header/control bytes"
    }
  ]
}
